contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint128 price, uint128 price2) public {
        // tester (address(this)) is a ward from deployment
        uint128 before0 = c.latestPrice();
        // deny ourselves
        c.deny(address(this));
        bool revertedWhileDenied;
        try c.updatePrice(price) { revertedWhileDenied = false; } catch { revertedWhileDenied = true; }
        uint128 afterDenied = c.latestPrice();
        uint256 tsAfterDenied = c.lastPriceUpdate();
        // rely ourselves again
        c.rely(address(this));
        bool revertedAfterRely;
        try c.updatePrice(price2) { revertedAfterRely = false; } catch { revertedAfterRely = true; }
        uint128 afterRely = c.latestPrice();
        uint256 tsAfterRely = c.lastPriceUpdate();
        assert(
            revertedWhileDenied
            && !revertedAfterRely
            && afterDenied == before0
            && tsAfterDenied == 0
            && afterRely == price2
            && tsAfterRely == block.timestamp
        );
    }
    receive() external payable {}
}

