contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint128 price, uint128 price2, bool selfDestructAuth) public {
        // Authorized: deployer (this contract) is a ward
        c.updatePrice(price);
        assert(c.latestPrice() == price && c.lastPriceUpdate() == block.timestamp);

        // Second update overwrites fully
        c.updatePrice(price2);
        assert(c.latestPrice() == price2 && c.lastPriceUpdate() == block.timestamp);

        // Unauthorized caller must revert and not change state
        bool reverted;
        if (selfDestructAuth) {
            // simulate an unauthorized call by denying ourselves then trying
            c.deny(address(this));
            try c.updatePrice(price2) { reverted = false; }
            catch { reverted = true; }
            assert(reverted);
            assert(c.latestPrice() == price2);
        } else {
            assert(c.latestPrice() == price2);
        }
    }
    receive() external payable {}
}

